#pragma once

#include "../models/ridge_payload.hpp"
#include "../models/alert_payload.hpp"
#include <vector>

namespace vitalgrid {

/**
 * @brief Autonomous Decision Engine: Flight Surgeon AI
 * Evaluates RIDGE telemetry against strict NASA biomedical standards
 */
class FlightSurgeonAI {
public:
    FlightSurgeonAI() = default;

    /**
     * @brief Evaluates an incoming RIDGE payload and returns detected alerts
     * @param payload Ingested astronaut telemetry snapshot
     * @return List of ClinicalAlert generated by breached thresholds
     */
    std::vector<ClinicalAlert> evaluate(const RidgePayload& payload);

    /**
     * @brief Computes dynamic clinical health score (0-100) based on RIDGE metrics
     */
    int compute_health_score(const RidgePayload& payload) const;

    // Hardcoded Clinical Thresholds (NASA Space Flight Standards)
    static constexpr double THRESHOLD_ACUTE_RAD_CRITICAL_MSV = 250.0;
    static constexpr double THRESHOLD_CAREER_RAD_CRITICAL_MSV = 600.0;
    static constexpr int    THRESHOLD_BP_SYS_CRITICAL = 155;
    static constexpr int    THRESHOLD_BP_DIA_CRITICAL = 95;
    static constexpr int    THRESHOLD_HR_CRITICAL_BPM = 110;
    static constexpr double THRESHOLD_ONSD_CRITICAL_MM = 5.8;
    static constexpr double THRESHOLD_PPCO2_CRITICAL_MMHG = 3.0;
    static constexpr int    THRESHOLD_SPO2_CRITICAL_PCT = 95;
    static constexpr double THRESHOLD_BODY_TEMP_CRITICAL_C = 38.5;
    static constexpr double THRESHOLD_SLEEP_WARN_HOURS = 6.0;
    static constexpr double THRESHOLD_HRV_DROP_WARN_PCT = 25.0;
    static constexpr int    THRESHOLD_BLINK_RATE_WARN_PER_MIN = 8; // Severe drop in spontaneous blink rate (< 8 blinks/min)
    static constexpr int    THRESHOLD_MICROSLEEP_WARN_COUNT = 1;   // Occurrence of >= 1 microsleep event (>500ms)
};

} // namespace vitalgrid
